<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, errorMessage } from '../services/api'
import { useAuthStore } from '../stores/auth'
import { useFeedbackStore } from '../stores/feedback'
const route=useRoute(), router=useRouter(), auth=useAuthStore(), feedback=useFeedbackStore(); const data=ref(null); const form=reactive({}); const saving=ref(false); const password=ref(''); const showPassword=ref(false); const sendingAccess=ref(false); const sendingPdf=ref('')
async function load(){ try { data.value=(await api.get(`/admin/users/${route.params.id}`)).data; const u=data.value.user; Object.assign(form,{full_name:u.fullName,email:u.email,nif:u.nif,company_name:u.companyName,phone:u.phone,address_line1:u.addressLine1,address_line2:u.addressLine2,postal_code:u.postalCode,city:u.city,country:u.country,role:u.role,active:u.active,admin_notes:u.adminNotes}) } catch(e){ feedback.show(errorMessage(e),'error') } }
async function save(){saving.value=true;try{await api.put(`/admin/users/${route.params.id}`,form);await load();feedback.show('Alterações guardadas.')}catch(e){feedback.show(errorMessage(e),'error')}finally{saving.value=false}}
async function resetPassword(){try{await api.put(`/admin/users/${route.params.id}/password`,{password:password.value});password.value='';feedback.show('Password atualizada e sessões antigas terminadas.')}catch(e){feedback.show(errorMessage(e),'error')}}
async function resendAccess(){if(!await feedback.confirm('Será criada uma nova password e enviada para o email deste utilizador. A password atual deixará de funcionar.','Reenviar acesso'))return;sendingAccess.value=true;try{await api.post(`/admin/users/${route.params.id}/welcome-email`);feedback.show('Nova password enviada por email.')}catch(e){feedback.show(errorMessage(e),'error')}finally{sendingAccess.value=false}}
async function sendOrderPdf(order,hidePrices){const label=hidePrices?'sem preços':'com preços';if(!await feedback.confirm(`Enviar o PDF ${label} para ${data.value.user.email || 'o email deste utilizador'}?`,'Enviar PDF'))return;const key=`${order.id}-${hidePrices?'plain':'priced'}`;sendingPdf.value=key;try{await api.post(`/admin/users/${route.params.id}/orders/${order.publicNumber}/email-pdf`,{hide_prices:hidePrices});feedback.show(`PDF ${label} enviado por email.`)}catch(e){feedback.show(errorMessage(e),'error')}finally{sendingPdf.value=''}}
async function remove(){if(!await feedback.confirm('Esta operação é definitiva. Eliminar este utilizador?','Eliminar utilizador'))return;try{await api.delete(`/admin/users/${route.params.id}`);feedback.show('Utilizador eliminado.');router.push('/admin/utilizadores')}catch(e){feedback.show(errorMessage(e),'error')}}
onMounted(load)
</script>
<template><div class="page"><v-btn to="/admin/utilizadores" variant="text" prepend-icon="mdi-arrow-left" class="mb-4">Voltar aos utilizadores</v-btn><v-skeleton-loader v-if="!data" type="article, article" /><template v-else><div class="page-head"><div><h1>{{ data.user.fullName }}</h1><p>@{{ data.user.username }} · {{ data.user.companyName || 'Sem empresa' }}</p></div><v-chip size="large" :color="form.active?'success':'grey'">{{ form.active?'Ativo':'Inativo' }}</v-chip></div>
  <v-row><v-col cols="12" lg="8"><v-card class="soft-card pa-6"><div class="text-h6 font-weight-bold mb-5">Dados do utilizador</div><v-row dense><v-col cols="12" md="6"><v-text-field v-model="form.full_name" label="Nome completo" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.company_name" label="Empresa" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" label="Email" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" label="Telefone" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.nif" label="NIF" /></v-col><v-col cols="12" md="6"><v-select v-model="form.role" label="Tipo" :items="[{title:'Cliente',value:'client'},{title:'Administrador',value:'admin'},{title:'Developer legado',value:'developer'}]" /></v-col><v-col cols="12"><v-text-field v-model="form.address_line1" label="Morada" /></v-col><v-col cols="12"><v-text-field v-model="form.address_line2" label="Complemento de morada" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.postal_code" label="Código postal" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.city" label="Localidade" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.country" label="País" /></v-col><v-col cols="12"><v-textarea v-model="form.admin_notes" label="Notas internas do administrador" rows="4" /></v-col><v-col cols="12"><v-switch v-model="form.active" color="success" label="Utilizador ativo" /></v-col></v-row><div class="d-flex justify-end"><v-btn color="primary" :loading="saving" @click="save">Guardar alterações</v-btn></div></v-card>
    <v-card class="soft-card mt-5"><v-card-title class="pa-5">Encomendas ({{ data.orders.length }})</v-card-title><v-list><v-list-item v-for="order in data.orders" :key="order.id" :to="`/admin/encomendas/${order.publicNumber}`" :title="order.publicNumber" :subtitle="`${order.orderStatusLabel} · ${Number(order.total).toFixed(2)} €`"><template #append><v-tooltip text="Enviar PDF com preços"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-file-pdf-box" size="small" variant="text" color="primary" :loading="sendingPdf===`${order.id}-priced`" @click.stop.prevent="sendOrderPdf(order,false)" /></template></v-tooltip><v-tooltip text="Enviar PDF sem preços"><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-file-pdf-box-outline" size="small" variant="text" color="secondary" :loading="sendingPdf===`${order.id}-plain`" @click.stop.prevent="sendOrderPdf(order,true)" /></template></v-tooltip><v-icon>mdi-chevron-right</v-icon></template></v-list-item></v-list><div v-if="!data.orders.length" class="empty-state">Sem encomendas.</div></v-card></v-col>
    <v-col cols="12" lg="4"><v-card class="soft-card pa-5 mb-5"><div class="text-h6 font-weight-bold mb-4">Definir nova password</div><v-text-field v-model="password" label="Nova password" :type="showPassword?'text':'password'" :append-inner-icon="showPassword?'mdi-eye-off':'mdi-eye'" hint="Mínimo de 8 caracteres" persistent-hint @click:append-inner="showPassword=!showPassword" /><v-btn block variant="tonal" color="primary" class="mt-4" @click="resetPassword">Atualizar password</v-btn><v-btn block variant="tonal" color="secondary" class="mt-2" prepend-icon="mdi-email-fast-outline" :loading="sendingAccess" :disabled="!data.user.email" @click="resendAccess">Reenviar acesso por email</v-btn><div v-if="!data.user.email" class="text-caption text-error mt-2">Este utilizador não tem email definido.</div></v-card><v-card class="soft-card pa-5"><div class="text-h6 font-weight-bold mb-2">Zona sensível</div><p class="text-body-2 text-medium-emphasis mb-4">Só é possível eliminar utilizadores sem histórico.</p><v-btn block color="error" variant="tonal" :disabled="Number(route.params.id)===auth.user.id" @click="remove">Eliminar utilizador</v-btn></v-card></v-col></v-row></template></div></template>
